package com.clavis.reader;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
final class FeedDiscoveryChecks {
 static int checks;static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 static JSONObject feed(String id,String title)throws Exception{return new JSONObject().put("feedId",id).put("title",title);}
 static JSONArray parse(JSONArray results,String kind)throws Exception{return FeedDiscovery.sources(new JSONObject().put("results",results),kind);}
 static boolean find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++)if(find(((ViewGroup)v).getChildAt(n),text))return true;return false;}
 static String run(Instrumentation test,boolean network)throws Exception{
  checks=0;JSONArray raw=new JSONArray().put(feed("feed/http://Example.com/feed","<b>Example</b> &amp; News")).put(feed("feed/https://example.com/feed","Duplicate")).put(feed("feed/javascript:alert(1)","Unsafe")).put(feed("feed/https://example.org/feed","Old").put("valid",false)).put(feed("feed/https://example.net/updates",""));
  JSONArray news=parse(raw,"News");check(news.length()==2,"Valid feeds only, HTTPS-upgraded URLs deduplicated");check(news.getJSONObject(0).getString("url").equals("https://example.com/feed"),"Safe HTTPS URL");check(news.getJSONObject(0).getString("title").equals("Example & News"),"Feed title cleaned");check(news.getJSONObject(1).getString("title").equals("example.net"),"Blank title uses host");check(parse(raw,"Journals").getJSONObject(0).getString("kind").equals("Journals"),"Articles category retained");check(news.getJSONObject(0).getString("kind").equals("News"),"News category retained");
  String encoded="https://example.com/a%2Fb?tag=a%26b&lang=en";check(parse(new JSONArray().put(feed("feed/"+encoded,"Encoded")),"News").getJSONObject(0).getString("url").equals(encoded),"Encoded paths and query preserved");check(parse(new JSONArray().put(feed("feed/https://user:password@example.com/rss","Credentials")),"News").length()==0,"Credential URL rejected");
  JSONArray many=new JSONArray();for(int n=0;n<40;n++)many.put(feed("feed/https://example.com/"+n,"Source "+n));check(parse(many,"News").length()==25,"Bounded result count");check(parse(new JSONArray(),"News").length()==0,"Empty search");
  boolean failed=false;try{FeedDiscovery.sources(new JSONObject(),"News");}catch(Exception e){failed=true;}check(failed,"Malformed response reported");failed=false;try{FeedDiscovery.sources(new JSONObject().put("success",false).put("results",new JSONArray()),"News");}catch(Exception e){failed=true;}check(failed,"Failed response reported");failed=false;try{parse(raw,"EPUB");}catch(Exception e){failed=true;}check(failed,"Unsupported kind rejected");
  MainActivity main=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{test.runOnMainSync(()->{main.library("News");check(find(main.getWindow().getDecorView(),"Search news online"),"News search shortcut");main.library("Journals");check(find(main.getWindow().getDecorView(),"Search articles online"),"Articles search shortcut");AlertDialog dialog=FeedCatalog.showSourceResults(main,"no match","Journals",new JSONArray());check(find(dialog.getWindow().getDecorView(),"No RSS sources found"),"Empty state shown");check(find(dialog.getWindow().getDecorView(),"Add custom RSS URL"),"Custom feed fallback");dialog.dismiss();});}finally{test.runOnMainSync(main::finish);}
  if(network){for(String kind:new String[]{"News","Journals"}){JSONArray results=FeedDiscovery.search(kind.equals("News")?"BBC":"cardiology",kind);check(results.length()>0,"Live "+kind+" discovery");boolean readable=false;for(int n=0;n<Math.min(3,results.length());n++)try{FeedStore.Feed downloaded=FeedStore.download(results.getJSONObject(n).getString("url"),kind);if(!downloaded.items.isEmpty()){readable=true;break;}}catch(Exception ignored){}check(readable,"Live discovered "+kind+" feed can be read");}}
  return checks+" source discovery checks passed"+(network?" (including live News and Articles feeds)":"");
 }
}